def get_section_text(sec_id: int) -> str:
    if sec_id not in SECTIONS:
        return get_hub_text()
    sec = SECTIONS[sec_id]
    lines = [
        f"{sec['title']}",
        f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
        f"ℹ️ {sec['desc']}",
        f"Всего в разделе: {len(sec['commands'])} команд\n"
    ]
    for name, desc, aliases in sec["commands"]:
        line = f"• {name} — {desc}"
        lines.append(line)
    
    lines.append(f"\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
    lines.append(f"💡 Для поиска любой команды напишите: «найти [слово]»")
    return "\n".join(lines)

def search_commands(query: str, limit: int = 15) -> str:
    q = query.strip().lower()
    if not q:
        return "⚠️ Введите поисковый запрос! Пример: «найти бан» или «найти бизнес»"
    
    matches: List[Tuple[str, str, int, str]] = []
    for sec_id, sec in SECTIONS.items():
        for name, desc, aliases in sec["commands"]:
            target = f"{name} {desc} {aliases}".lower()
            if q in target:
                matches.append((name, desc, sec_id, sec["title"].split(":")[0]))

    if not matches:
        return (
            f"🔍 По запросу «{query}» ничего не найдено.\n"
            f"Попробуйте другое слово или откройте главное меню: «команды»!"
        )

    out = [
        f"🔍 РЕЗУЛЬТАТЫ ПОИСКА: «{query}» (найдено: {len(matches)})",
        f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
    ]
    for name, desc, sec_id, sec_title in matches[:limit]:
        out.append(f"• {name} — {desc} ({sec_title})")
    
    if len(matches) > limit:
        out.append(f"\n...и ещё {len(matches) - limit} команд! Уточните поисковый запрос.")
    
    out.append(f"\n📖 Напишите «команды», чтобы открыть полное оглавление.")
    return "\n".join(out)

def get_hub_keyboard() -> str:
    kb = Keyboard(inline=True)
    # 👑 РЯД 1: МОДЕРАЦИЯ И БЕЗОПАСНОСТЬ (Рубиновый строгий блок)
    kb.add(Text("👑 1. Модерация"), color=KeyboardButtonColor.NEGATIVE)
    kb.add(Text("🛡 2. Баны/Варны"), color=KeyboardButtonColor.NEGATIVE)
    kb.row()
    # ⚙️ РЯД 2: НАСТРОЙКИ И ЭКОНОМИКА (Контрастный Белый + Изумрудный)
    kb.add(Text("⚙️ 3. Настройки"), color=KeyboardButtonColor.PRIMARY)
    kb.add(Text("💰 4. Экономика"), color=KeyboardButtonColor.POSITIVE)
    kb.row()
    # 🏢 РЯД 3: БИЗНЕС-ИМПЕРИЯ И АЗАРТ (Контрастный Белый + Рубиновый)
    kb.add(Text("🏢 5. Бизнесы/Дома"), color=KeyboardButtonColor.PRIMARY)
    kb.add(Text("🎰 6. Казино/Игры"), color=KeyboardButtonColor.NEGATIVE)
    kb.row()
    # ⚔️ РЯД 4: ДАНЖИ И ПРОГРЕСС (Рубиновый + Изумрудный)
    kb.add(Text("⚔️ 7. Данжи/Фарм"), color=KeyboardButtonColor.NEGATIVE)
    kb.add(Text("📜 8. Квесты/VIP"), color=KeyboardButtonColor.POSITIVE)
    kb.row()
    # 🐉 РЯД 5: КЛАНЫ И СОЦИАЛЬНОЕ (Рубиновый + Изумрудный)
    kb.add(Text("🐉 9. Кланы/Боссы"), color=KeyboardButtonColor.NEGATIVE)
    kb.add(Text("💘 10. Семья/КПЗ"), color=KeyboardButtonColor.POSITIVE)
    kb.row()
    # 💖 РЯД 6: ИНТЕРАКТИВ И РП-ДЕЙСТВИЯ (Изумрудная романтика + Рубиновые бои)
    kb.add(Text("💖 11. РП Романтика"), color=KeyboardButtonColor.POSITIVE)
    kb.add(Text("🔥 12. РП Боевые"), color=KeyboardButtonColor.NEGATIVE)
    return kb.get_json()

def get_section_keyboard(sec_id: int) -> str:
    kb = Keyboard(inline=True)
    prev_sec = 12 if sec_id == 1 else sec_id - 1
    next_sec = (sec_id % 12) + 1
    # Ряд 1: Быстрая навигация вперед/назад и главное меню
    kb.add(Text(f"◀️ Раздел {prev_sec}"), color=KeyboardButtonColor.PRIMARY)
    kb.add(Text("📖 Все разделы"), color=KeyboardButtonColor.POSITIVE)
    kb.add(Text(f"Раздел {next_sec} ▶️"), color=KeyboardButtonColor.PRIMARY)
    kb.row()
    # Ряд 2: Быстрый поиск и добавление бота
    kb.add(Text("🔍 Поиск команд"), color=KeyboardButtonColor.PRIMARY)
    kb.add(Text("➕ В беседу"), color=KeyboardButtonColor.POSITIVE)
    return kb.get_json()
